  insert into public.docs (collection, id, data) values ('tasks', 'ltvgx0n35hrkw', replace($j${"archived": false, "assignees": [], "column": "todo", "como": "Product manager", "createdAt": 1793315242630, "createdBy": "__ADMIN__", "criteria": [], "description": "Crear reporte de rendimiento y uso de conductores en el CMS de QuickTrack\n\nComo usuario admin de QuickTrack, quiero consultar un reporte consolidado del uso y rendimiento de los conductores, para identificar rápidamente el nivel de uso de cada conductor, detectar conductores con poco o ningún uso y analizar el comportamiento de las entregas durante un periodo determinado.\n\nObjetivo\nIncorporar al CMS de QuickTrack un reporte que permita consultar, filtrar y analizar la actividad de los conductores a partir de sus entregas realizadas y días con actividad.\nEl reporte debe permitir visualizar información consolidada y detallada, manteniendo una experiencia equivalente al dashboard de referencia.\n\nhttps://qt-driver-dashboard.vercel.app/", "docs": [], "doneAt": null, "end": "", "milestoneId": "", "order": 1.5, "para": "Con el fin de poder realizar un seguimiento a la operación", "priority": "media", "projectId": "vhwn242o4okfi", "quiero": "tener dentro de QuickTrack el reporte de rendimiento y uso de conductores para cada carrier", "start": "", "subtasks": [], "title": "Reporte drivers en el admin de QT", "updatedAt": 1793315256395}$j$, '__ADMIN__', admin_id)::jsonb) on conflict (collection, id) do nothing;
